package bottlesong

import (
	"fmt"
	"strings"
	"unicode"
)

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines,
			fmt.Sprintf("%s green bottles hanging on the wall,", title(phrase(n))),
			fmt.Sprintf("%s green bottles hanging on the wall,", title(phrase(n))),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green bottle%s hanging on the wall.", title(phrase(n-1)), suffix(n-1)),
		)
	}
	return lines
}

// phrase returns the word form of the bottle count, e.g. "ten bottles" or "one bottle".
func phrase(n int) string {
	switch {
	case n == 0:
		return "no bottles"
	case n == 1:
		return "one bottle"
	default:
		return fmt.Sprintf("%d bottles", n)
	}
}

func suffix(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// title uppercases the first rune of the string.
func title(s string) string {
	for i, r := range s {
		return string(unicode.ToUpper(r)) + s[i+len(string(r)):]
	}
	return s
}

var _ = strings.TrimSpace

