package bottlesong

import (
	"fmt"
	"unicode"
)

var numberWords = []string{
	"no", "one", "two", "three", "four", "five",
	"six", "seven", "eight", "nine", "ten",
}

func Recite(startBottles, takeDown int) []string {
	var lines []string
	for n := startBottles; n > startBottles-takeDown; n-- {
		if len(lines) > 0 {
			lines = append(lines, "")
		}
		lines = append(lines,
			fmt.Sprintf("%s green %s hanging on the wall,", title(numberWords[n]), bottleWord(n)),
			fmt.Sprintf("%s green %s hanging on the wall,", title(numberWords[n]), bottleWord(n)),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green %s hanging on the wall.", title(numberWords[n-1]), bottleWord(n-1)),
		)
	}
	return lines
}

// bottleWord returns "bottle" for a single bottle and "bottles" otherwise.
func bottleWord(n int) string {
	if n == 1 {
		return "bottle"
	}
	return "bottles"
}

// title uppercases the first rune of the string.
func title(s string) string {
	for i, r := range s {
		return string(unicode.ToUpper(r)) + s[i+len(string(r)):]
	}
	return s
}

